import{z as o,x as i,o as s,c as l,q as t,j as B,D as E,d as e,s as n,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"CRC 在帧上","description":"","frontmatter":{"title":"CRC 在帧上","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/frame-crc.md","filePath":"cs/frame-crc.md","lastUpdated":1791413859000}'),p={name:"cs/frame-crc.md"};function d(c,a,D,m,S,F){const C=i("Mermaid");return s(),l("div",null,[a[2]||(a[2]=t('<h1 id="crc-在帧上" tabindex="-1">CRC 在帧上 <a class="header-anchor" href="#crc-在帧上" aria-label="Permalink to &quot;CRC 在帧上&quot;">​</a></h1><div class="epigraph"><p>帧尾的校验序列是这一跳的多项式余数；它发现比特翻转，不证明端到端文件完好。</p><footer>—— 据 Peterson and Brown 对 CRC；IEEE 802.3 FCS；Kurose and Ross 整理</footer></div><p><a href="/cs/frame-mac">上一课</a>给出帧：MAC、类型、载荷、FCS。本课不重画以太网头。缺口是 FCS 如何从比特串算出、错了谁丢帧，以及它和<a href="/cs/layering-e2e">端到端</a>校验为何必须并存。<a href="/cs/error-correcting-intuition">纠错码直觉</a>已在信息论课出现过；这里只把它接到链路上的 CRC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>介质噪声会翻比特。若只靠上层发现，一跳上的坏帧仍会占用邻机与交换机。链路把循环冗余校验（CRC）做成帧的一部分：把载荷当多项式，除以约定生成多项式，余数写入 FCS。接收方重算，不合则丢。缺口不是新的 MAC 地址，而是<strong>这一跳的检错合同</strong>。</p><p><span class="marginnote">FCS（帧校验序列）就是帧尾巴上那 4 个字节的「余数收据」：发送方把整帧当一个大二进制数除以约定多项式，把余数装进去；接收方重除一遍，对不上号就整帧丢弃。</span></p><p><span class="marginnote">数字感受一下检错能力：以太网用的 CRC-32 能查出所有长度不超过 32 位的突发错误和所有奇数个比特错；随机噪声下的漏检概率在 \\(2^{-32}\\) 量级——大约每 40 多亿个坏帧才可能溜过去一个。</span></p><p><span class="marginnote">CRC 擅长短突发错误。它通常只检不纠：纠需要更多冗余与更复杂的接收机，以太网选择丢帧让上层重传。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送前对覆盖范围（头+载荷，具体标准写明）做 CRC，附加 FCS。接收方用同一多项式；余数非约定值则丢，不把坏载荷交给 <a href="/cs/ip-subnet">IP</a>。交换机存储转发时常验 FCS 再出门；直通交换可能转发已坏的帧，这是延迟与检错的取舍，本课不把直通当默认。</p>',10)),(s(),B(A,null,{default:E(()=>[n(C,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAY%5B%22MAC%20%E5%A4%B4%E4%B8%8E%E8%BD%BD%E8%8D%B7%22%5D%20--%3E%20CRC%5B%22CRC%20%E4%BD%99%E6%95%B0%E5%86%99%E5%85%A5%20FCS%22%5D%0A%20%20CRC%20--%3E%20WIRE%5B%22%E4%BB%8B%E8%B4%A8%22%5D%0A%20%20WIRE%20--%3E%20CHK%5B%22%E9%87%8D%E7%AE%97%E4%B8%8D%E5%90%88%E5%88%99%E4%B8%A2%22%5D%0A%20%20CHK%20--%3E%20UP%5B%22%E5%90%88%E5%88%99%E4%BA%A4%E7%BB%99%E4%BB%A5%E5%A4%AA%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("CRC 把「这一跳尽力」写成可执行的过滤：网卡与交换芯片在 "),r("a",{href:"/cs/io-dma"},"DMA"),e(" 之前就能拒收。端到端论证仍然成立：中间节点内存、路由软件、磁盘都在 FCS 覆盖之外；文件传送仍要两端核对。传输层校验和（后课 UDP/TCP）覆盖的是伪首部与载荷，对象不是同一跳的电信号。")],-1)),(s(),B(A,null,{default:E(()=>[n(C,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20H1%5B%22%E4%B8%BB%E6%9C%BA%20A%20%E7%AE%97%20FCS%20%E5%8F%91%E5%B8%A7%22%5D%20--%3E%20SW%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%EF%BC%9A%E5%AD%98%E5%82%A8%E8%BD%AC%E5%8F%91%E5%85%88%E9%AA%8C%20FCS%22%5D%0A%20%20SW%20--%3E%7C%22FCS%20%E5%9D%8F%22%7C%20DROP%5B%22%E6%AD%A4%E8%B7%B3%E4%B8%A2%E5%BC%83%22%5D%0A%20%20SW%20--%3E%7C%22FCS%20%E5%A5%BD%22%7C%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20R%20--%3E%20MEM%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E5%86%85%E5%AD%98%E4%B8%8E%E8%BD%AF%E4%BB%B6%EF%BC%9AFCS%20%E4%B8%8D%E5%86%8D%E8%A6%86%E7%9B%96%22%5D%0A%20%20MEM%20--%3E%20H2%5B%22%E4%B8%BB%E6%9C%BA%20B%20%E9%AA%8C%E6%9C%80%E5%90%8E%E4%B8%80%E8%B7%B3%20FCS%22%5D%0A%20%20H2%20--%3E%20APP%5B%22%E6%96%87%E4%BB%B6%E4%BB%8D%E8%A6%81%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%A0%B8%E5%AF%B9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">这张图回答「每一跳都验 FCS，为什么端到端校验仍不可省」：FCS 只在链路段上有效，帧在路由器内存里排队、被软件改写时都不受它保护——中间环节引入的损坏要到两端的应用层核对才会现形。</span></p><p><span class="marginnote">初学者容易以为 FCS 能防篡改——实际上攻击者改完载荷后可以顺手把余数重算一遍，FCS 照样通过。它防的是随机噪声，不防恶意的人；防篡改需要带密钥的 MAC/AEAD，是后课的缺口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把生成多项式的本原性证明写进主干，不引入以太网之外全部 FCS 宽度。也不把 CRC 当成抗恶意篡改：未认证的多项式余数挡不住有意改帧。完整性作为安全性质是后课 MAC/AEAD 的缺口。</p><p>共享介质上两台同时发，FCS 几乎必错——那是冲突，下一课 CSMA，不是「再换一个多项式」。</p><p>后课默认：坏帧在链路上被丢掉。多台如何抢介质、交换机如何缩小冲突域，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCS 是一跳 CRC：发现翻转，默认丢帧。</li><li>代替不了端到端校验，也不是认证。</li><li>冲突与交换是下一课。</li><li>出处：IEEE 802.3；Kurose and Ross；对照 Peterson 对 CRC 的经典表述。</li></ul>',8))])}const u=o(p,[["render",d]]);export{h as __pageData,u as default};
